# =====================================================================
# cavallo_logo_and_icon_patch.ps1
#
# 1) Replaces the default Flutter launcher icon / launch screen with the
#    Cavallo icon (Android + iOS).
# 2) Shows the Cavallo logo (the same wordmark as the Home top bar) on EVERY
#    screen: all screens now build CavalloAppBar instead of AppBar.
#
# Nothing else in the app is touched (colors, fonts, layouts, texts).
#
# Run from the Flutter project root (the folder with pubspec.yaml):
#     powershell -ExecutionPolicy Bypass -File .\cavallo_logo_and_icon_patch.ps1
# Preview only, no file is written:
#     powershell -ExecutionPolicy Bypass -File .\cavallo_logo_and_icon_patch.ps1 -DryRun
#
# Safe to run twice: files that are already patched are reported and skipped.
# To undo everything:  git checkout -- .   and delete the new files (git clean).
# =====================================================================
param([switch]$DryRun)

$ErrorActionPreference = 'Stop'
$root = (Get-Location).ProviderPath
$utf8 = New-Object System.Text.UTF8Encoding($false)
$script:changed = 0
$script:failed  = New-Object 'System.Collections.Generic.List[string]'

function Say([string]$msg, [string]$color = 'Gray') { Write-Host $msg -ForegroundColor $color }
function Get-Full([string]$rel) { return [System.IO.Path]::GetFullPath((Join-Path $root $rel)) }
function Norm([string]$s) { return $s.Replace("`r`n", "`n") }

function Save-Text([string]$full, [string]$text, [bool]$crlf) {
    if ($crlf) { $text = $text.Replace("`n", "`r`n") }
    if (-not $DryRun) { [System.IO.File]::WriteAllText($full, $text, $utf8) }
}

# Inserts $imp after the last complete one-line import. No-op if present.
function Add-Import([System.Collections.Generic.List[string]]$lines, [string]$imp) {
    foreach ($l in $lines) { if ($l.Trim() -eq $imp) { return } }
    $idx = -1
    for ($i = 0; $i -lt $lines.Count; $i++) {
        if ($lines[$i] -match '^import\s+''[^'']+''(\s+(as|show|hide)\s+[^;]+)?;\s*$') { $idx = $i }
    }
    if ($idx -lt 0) { throw 'no import line found' }
    $lines.Insert($idx + 1, $imp)
}

function Add-NewText([string]$rel, [string]$content) {
    $full = Get-Full $rel
    $content = (Norm $content).TrimEnd("`n") + "`n"
    if (Test-Path -LiteralPath $full) {
        if ((Norm ([System.IO.File]::ReadAllText($full))) -ceq $content) { Say "  =  $rel (already up to date)"; return }
    }
    if (-not $DryRun) {
        [void][System.IO.Directory]::CreateDirectory([System.IO.Path]::GetDirectoryName($full))
        [System.IO.File]::WriteAllText($full, $content, $utf8)
    }
    Say "  +  $rel" 'Green'
    $script:changed++
}

function Add-Binary([string]$rel, [string]$b64) {
    $full = Get-Full $rel
    if (Test-Path -LiteralPath $full) {
        if ([System.Convert]::ToBase64String([System.IO.File]::ReadAllBytes($full)) -ceq $b64) { Say "  =  $rel (already up to date)"; return }
    }
    if (-not $DryRun) {
        [void][System.IO.Directory]::CreateDirectory([System.IO.Path]::GetDirectoryName($full))
        [System.IO.File]::WriteAllBytes($full, [System.Convert]::FromBase64String($b64))
    }
    Say "  +  $rel" 'Green'
    $script:changed++
}

# AppBar( -> CavalloAppBar( on code lines (comments untouched) + the import.
function Update-AppBarFile([string]$rel, [string]$imp) {
    $full = Get-Full $rel
    if (-not (Test-Path -LiteralPath $full)) { throw "file not found: $rel" }
    $raw = [System.IO.File]::ReadAllText($full)
    $crlf = $raw.Contains("`r`n")
    $old = Norm $raw
    $lines = New-Object 'System.Collections.Generic.List[string]'
    $lines.AddRange([string[]]($old.Split([char]10)))
    $pattern = '(?<![A-Za-z0-9_])AppBar\('
    $count = 0
    for ($i = 0; $i -lt $lines.Count; $i++) {
        if ($lines[$i].TrimStart().StartsWith('//')) { continue }
        $n = [regex]::Matches($lines[$i], $pattern).Count
        if ($n -gt 0) {
            $lines[$i] = [regex]::Replace($lines[$i], $pattern, 'CavalloAppBar(')
            $count += $n
        }
    }
    if (($lines -join "`n") -match 'CavalloAppBar\(') { Add-Import $lines $imp }
    $new = $lines -join "`n"
    if ($new -ceq $old) { Say "  =  $rel (already patched)"; return }
    Save-Text $full $new $crlf
    Say "  ~  $rel ($count AppBar -> CavalloAppBar)" 'Cyan'
    $script:changed++
}

# One exact regex edit (must match exactly once) + imports.
function Update-WithRegex([string]$rel, [string]$marker, [string]$pattern, [string]$replacement, [string[]]$imports) {
    $full = Get-Full $rel
    if (-not (Test-Path -LiteralPath $full)) { throw "file not found: $rel" }
    $raw = [System.IO.File]::ReadAllText($full)
    $crlf = $raw.Contains("`r`n")
    $old = Norm $raw
    $t = $old
    if (-not $t.Contains($marker)) {
        $found = [regex]::Matches($t, $pattern).Count
        if ($found -ne 1) { throw "expected exactly 1 place to edit in $rel but found $found - this file differs from the version this patch was made for" }
        $t = [regex]::Replace($t, $pattern, (Norm $replacement))
    }
    $lines = New-Object 'System.Collections.Generic.List[string]'
    $lines.AddRange([string[]]($t.Split([char]10)))
    foreach ($imp in $imports) { Add-Import $lines $imp }
    $new = $lines -join "`n"
    if ($new -ceq $old) { Say "  =  $rel (already patched)"; return }
    Save-Text $full $new $crlf
    Say "  ~  $rel" 'Cyan'
    $script:changed++
}

function Step([string]$title, [scriptblock]$body) {
    Say ''
    Say $title 'White'
    & $body
}
function Try-Do([string]$what, [scriptblock]$body) {
    try { & $body } catch { Say "  !  $what : $($_.Exception.Message)" 'Red'; $script:failed.Add("$what : $($_.Exception.Message)") }
}

# ---------------------------------------------------------------- checks
if (-not (Test-Path (Join-Path $root 'pubspec.yaml')) -or -not (Test-Path (Join-Path $root 'lib'))) {
    Say 'STOP: run this from the Flutter project root (the folder that holds pubspec.yaml and lib\).' 'Red'; exit 1
}
if ([System.IO.File]::ReadAllText((Join-Path $root 'pubspec.yaml')) -notmatch '(?m)^name:\s*social_commerce_app\s*$') {
    Say 'STOP: pubspec.yaml is not the social_commerce_app project.' 'Red'; exit 1
}
foreach ($need in @('lib/core/shell/home_top_bar.dart', 'lib/core/theme/app_colors.dart', 'lib/core/l10n/l10n_context.dart', 'lib/main.dart')) {
    if (-not (Test-Path (Get-Full $need))) {
        Say "STOP: $need not found. This patch is for the branch that has the Home top bar (part-111 / P-113 and later)." 'Red'; exit 1
    }
}
if ($DryRun) { Say '*** DRY RUN - no file will be written ***' 'Yellow' }

