import 'package:flutter/material.dart';

import '../l10n/l10n_context.dart';
import '../theme/app_colors.dart';

/// The Cavallo wordmark, drawn exactly like the one at the start of the Home
/// top bar (`HomeTopBar`): the localized brand text `homeWordmark`, in
/// `titleLarge`, weight 800, letter spacing 0.5, in the brand text colour.
///
/// It is the single widget every screen uses to show the logo, so the logo
/// looks the same everywhere. Screens normally do not use it directly: they
/// build a `CavalloAppBar` (`cavallo_app_bar.dart`), which places it.
///
/// * [compact] draws it one text step smaller (`titleMedium`) for crowded
///   places such as the story viewer header.
/// * [color] replaces the brand text colour (the story viewer is always
///   black, whatever the theme, so it passes the dark-theme brand tint).
class CavalloLogo extends StatelessWidget {
  const CavalloLogo({this.compact = false, this.color, super.key});

  /// Draws the logo one text step smaller.
  final bool compact;

  /// Overrides the brand text colour. Null uses `AppColors.brandText`.
  final Color? color;

  /// Key of the logo text.
  static const Key logoKey = ValueKey<String>('cavallo-logo');

  @override
  Widget build(BuildContext context) {
    final TextTheme textTheme = Theme.of(context).textTheme;
    final TextStyle? base =
        compact ? textTheme.titleMedium : textTheme.titleLarge;
    return Text(
      context.l10n.homeWordmark,
      key: logoKey,
      maxLines: 1,
      style: base?.copyWith(
        fontWeight: FontWeight.w800,
        letterSpacing: 0.5,
        color: color ?? context.appColors.brandText,
      ),
    );
  }
}
'@ }
    Try-Do 'lib/core/widgets/cavallo_app_bar.dart' { Add-NewText 'lib/core/widgets/cavallo_app_bar.dart' @'
import 'package:flutter/material.dart';

import 'cavallo_logo.dart';

/// A drop-in replacement for [AppBar] that also shows the Cavallo logo.
///
/// Every screen of the app builds this instead of a plain [AppBar], so no
/// screen is without the logo. It takes the same arguments the app's screens
/// already pass to [AppBar] and hands them to a real [AppBar] unchanged, so
/// the title, the back button, the bottom tab bar, the height and every theme
/// value stay exactly as they were.
///
/// ## Where the logo goes
/// The logo is added as the FIRST entry of `actions`: it sits next to the
/// title, and the screen's own action icons keep their place at the end of
/// the bar. In Arabic (RTL) the bar mirrors like any other [AppBar].
///
/// The Home tab does not use this widget: `HomeTopBar` already shows the logo
/// at the start of its bar.
///
/// A test (`cavallo_app_bar_test.dart`) fails if any screen builds a plain
/// [AppBar] again.
class CavalloAppBar extends StatelessWidget implements PreferredSizeWidget {
  const CavalloAppBar({
    super.key,
    this.leading,
    this.automaticallyImplyLeading = true,
    this.title,
    this.actions,
    this.bottom,
    this.titleSpacing,
    this.centerTitle,
  });

  final Widget? leading;
  final bool automaticallyImplyLeading;
  final Widget? title;
  final List<Widget>? actions;
  final PreferredSizeWidget? bottom;
  final double? titleSpacing;
  final bool? centerTitle;

  @override
  Size get preferredSize =>
      Size.fromHeight(kToolbarHeight + (bottom?.preferredSize.height ?? 0.0));

  @override
  Widget build(BuildContext context) {
    final List<Widget> screenActions = actions ?? const <Widget>[];
    return AppBar(
      leading: leading,
      automaticallyImplyLeading: automaticallyImplyLeading,
      title: title,
      titleSpacing: titleSpacing,
      centerTitle: centerTitle,
      bottom: bottom,
      actions: <Widget>[
        Padding(
          padding: EdgeInsetsDirectional.only(
            start: 8,
            end: screenActions.isEmpty ? 16 : 4,
          ),
          child: const CavalloLogo(),
        ),
        ...screenActions,
      ],
    );
  }
}
'@ }
    Try-Do 'test/core/widgets/cavallo_app_bar_test.dart' { Add-NewText 'test/core/widgets/cavallo_app_bar_test.dart' @'
import 'dart:io';

import 'package:flutter/material.dart';
import 'package:flutter_test/flutter_test.dart';
import 'package:social_commerce_app/core/theme/app_theme.dart';
import 'package:social_commerce_app/core/widgets/cavallo_app_bar.dart';
import 'package:social_commerce_app/core/widgets/cavallo_logo.dart';
import 'package:social_commerce_app/l10n/app_localizations.dart';

/// The Cavallo logo is on every screen: `CavalloAppBar` shows it, and no
/// screen may build a plain `AppBar` (which would have no logo).

Widget _host(Widget home, {Locale locale = const Locale('en')}) {
  return MaterialApp(
    localizationsDelegates: AppLocalizations.localizationsDelegates,
    supportedLocales: AppLocalizations.supportedLocales,
    locale: locale,
    theme: AppTheme.light,
    home: home,
  );
}

void main() {
  testWidgets('shows the logo and keeps the title and the screen actions', (
    WidgetTester tester,
  ) async {
    await tester.pumpWidget(
      _host(
        Scaffold(
          appBar: CavalloAppBar(
            title: const Text('Some page'),
            actions: <Widget>[
              IconButton(
                key: const Key('screen-action'),
                icon: const Icon(Icons.refresh),
                onPressed: () {},
              ),
            ],
          ),
        ),
      ),
    );

    expect(find.byKey(CavalloLogo.logoKey), findsOneWidget);
    expect(find.text('Cavallo'), findsOneWidget);
    expect(find.text('Some page'), findsOneWidget);
    expect(find.byKey(const Key('screen-action')), findsOneWidget);
    expect(find.byType(AppBar), findsOneWidget);
  });

  testWidgets('shows the logo with no actions and in Arabic', (
    WidgetTester tester,
  ) async {
    await tester.pumpWidget(
      _host(
        const Scaffold(appBar: CavalloAppBar(title: Text('Some page'))),
        locale: const Locale('ar'),
      ),
    );

    expect(find.byKey(CavalloLogo.logoKey), findsOneWidget);
    expect(find.text('Cavallo'), findsOneWidget);
  });

  test('has the same height as a plain AppBar, with and without a bottom', () {
    const CavalloAppBar plain = CavalloAppBar();
    expect(plain.preferredSize, AppBar().preferredSize);

    const PreferredSize bottom = PreferredSize(
      preferredSize: Size.fromHeight(48),
      child: SizedBox(),
    );
    const CavalloAppBar withBottom = CavalloAppBar(bottom: bottom);
    expect(withBottom.preferredSize, AppBar(bottom: bottom).preferredSize);
  });

  test('no screen builds a plain AppBar', () {
    // HomeTopBar draws the logo itself; CavalloAppBar wraps the real AppBar.
    const Set<String> allowed = <String>{
      'lib/core/shell/home_top_bar.dart',
      'lib/core/widgets/cavallo_app_bar.dart',
    };
    final RegExp plainAppBar = RegExp(r'(?<![A-Za-z0-9_])AppBar\(');
    final List<String> offenders = <String>[];

    for (final FileSystemEntity entity in Directory(
      'lib',
    ).listSync(recursive: true)) {
      if (entity is! File || !entity.path.endsWith('.dart')) continue;
      final String path = entity.path.replaceAll('\\', '/');
      if (allowed.contains(path)) continue;
      final List<String> lines = entity.readAsLinesSync();
      for (int i = 0; i < lines.length; i++) {
        if (lines[i].trimLeft().startsWith('//')) continue;
        if (plainAppBar.hasMatch(lines[i])) offenders.add('$path:${i + 1}');
      }
    }

    expect(
      offenders,
      isEmpty,
      reason:
          'Use CavalloAppBar (core/widgets/cavallo_app_bar.dart) so the '
          'Cavallo logo is on every screen.',
    );
  });
}
'@ }
}

